import {OFFERS,COMPANY,DEMO_DATE} from './data.js';
import {money,number,percent,calculate,validateNeed,parseNeeds,matchNeed} from './domain.js';
import {loadState,saveState,event as addEvent} from './store.js';
import {icon,product,logo} from './icons.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(s,year=false)=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',...(year?{year:'numeric'}:{})}).format(new Date(s+'T12:00:00'));
let state=loadState(),view='offers',category='Все',query='',sort='saving',orderFilter='all',dialog=null,detailTab='terms',toastTimer,lastFocus;
const el=$('#app'),overlay=$('#overlay-root');
const totals=()=>OFFERS.reduce((a,o)=>{const c=calculate(o);return {saving:a.saving+c.saving,standalone:a.standalone+c.standaloneTotal,group:a.group+c.groupTotal};},{saving:0,standalone:0,group:0});
const activeOrders=()=>state.orders.filter(o=>o.status!=='cancelled');
const save=()=>{if(!saveState(state))toast('Изменения доступны только до закрытия страницы');};
const offerById=id=>OFFERS.find(o=>o.id===id);
const orderFor=id=>activeOrders().find(o=>o.offerId===id);
function button(text,action,cls='secondary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function render(){
 const t=totals(),active=activeOrders();
 el.innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Навигация банка"><a href="#offers" class="brand" aria-label="Бизнес Платформа, Оптима">${logo}<i class="brand-divider"></i><span>Бизнес</span></a><button class="side-company" data-action="company"><span class="company-avatar">С</span><span>${esc(COMPANY.name)}<small>Тестовая компания</small></span>${icon('down','sm')}</button><nav class="side-nav"><button class="nav-item" data-action="bank" data-name="Главная">${icon('home')}Главная</button><button class="nav-item" data-action="bank" data-name="Счета и платежи">${icon('wallet')}Счета и платежи</button><button class="nav-item" data-action="bank" data-name="Бизнес-карты">${icon('card')}Бизнес-карты</button><button class="nav-item" data-action="bank" data-name="Кредиты">${icon('briefcase')}Кредиты</button><button class="nav-item" data-action="bank" data-name="Депозиты">${icon('chart')}Депозиты</button><div class="nav-section">Сервисы для бизнеса</div><button class="nav-item active" data-action="view" data-view="offers">${icon('box')}Оптима<i class="nav-dot"></i></button><button class="nav-item" data-action="view" data-view="analytics">${icon('chart')}Аналитика закупок</button><button class="nav-item" data-action="view" data-view="needs">${icon('file')}Мои потребности</button></nav><div class="sidebar-bottom"><button class="sidebar-help" data-action="help">${icon('help')}Помощь и поддержка</button><div class="demo-mark"><i></i>Демонстрационный режим</div></div></aside><div class="mobile-backdrop" data-action="mobile-close"></div><div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="mobile" aria-label="Открыть меню">${icon('menu')}</button><div class="topbar-title">${icon('briefcase','sm')}Бизнес Платформа</div><div class="topbar-right"><span class="topbar-date">${date(DEMO_DATE)}</span><button class="icon-button" data-action="global-search" aria-label="Поиск">${icon('search')}</button><button class="icon-button ${state.notificationsRead?'':'notice-dot'}" data-action="notifications" aria-label="Уведомления">${icon('bell')}</button><button class="profile-btn" data-action="profile"><span class="user-avatar">АС</span><span>Александр С.</span>${icon('down','sm')}</button></div></header><main id="main" class="content"><div class="breadcrumb"><a href="#offers">Сервисы для бизнеса</a>${icon('chevron')}<span>Совместные закупки</span></div><div class="page-heading"><div><div class="page-heading-left"><span class="optima-sign">${icon('box')}</span><h1>Оптима</h1></div><p>Совместные закупки с выгодой для вашего бизнеса</p></div><button class="text-button" data-action="help">${icon('help','sm')}Как это работает</button></div>${view==='offers'?`<section class="hero" aria-label="Возможности совместных закупок"><div class="hero-main"><h2>Оптовые условия.<br>Только нужный вам объём.</h2><p>Объединяйте закупки с другими компаниями и получайте более выгодные предложения поставщиков.</p><div class="hero-actions">${button(icon('plus','sm')+'Добавить потребность','new-need','primary')}${button(icon('upload','sm')+'Загрузить документ','upload','secondary')}</div></div><div class="hero-value"><span class="label">Потенциальная экономия</span><strong class="amount">${money(t.saving)}</strong><small>По предложениям в подборке,<br>с учётом стоимости доставки</small><span class="trend">${icon('chart','sm')}До ${percent(Math.max(...OFFERS.map(o=>calculate(o).savingPercent)))} в этой подборке</span></div></section>`:''}<section class="metrics" aria-label="Сводка закупок"><div class="metric"><div><div class="metric-label">Предложений для вас</div><div class="metric-value amount">${OFFERS.length}<span class="sr-only"> предложений</span></div><div class="metric-note">В выбранном регионе</div></div><span class="metric-icon">${icon('bag')}</span></div><div class="metric"><div><div class="metric-label">${active.length?'Ожидаемая экономия':'Экономия в подборке'}</div><div class="metric-value green amount">${money(active.length?active.reduce((a,o)=>a+o.calculation.saving,0):t.saving)}</div><div class="metric-note">${active.length?'По вашим активным заявкам':'До подтверждения условий'}</div></div><span class="metric-icon">${icon('chart')}</span></div><div class="metric"><div><div class="metric-label">Активные закупки</div><div class="metric-value amount">${active.length}</div><div class="metric-note">${active.length?'Заявки на участие':'Пока не участвуете в закупках'}</div></div><span class="metric-icon">${icon('users')}</span></div></section><nav class="tabs" aria-label="Разделы Оптимы">${[['offers','Предложения',OFFERS.length],['orders','Мои закупки',active.length],['needs','Потребности',state.needs.length],['analytics','Аналитика',null]].map(([id,label,count])=>`<button class="tab ${view===id?'active':''}" data-action="view" data-view="${id}" ${view===id?'aria-current="page"':''}>${label}${count!==null?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</nav><div id="view-content" class="page-enter">${view==='offers'?offersView():view==='orders'?ordersView():view==='needs'?needsView():analyticsView()}</div><footer class="footer"><span class="data-note">${icon('shield')}Прототип для Академии Финтеха. Все данные демонстрационные.</span><button data-action="privacy">Данные и условия</button></footer></main></div></div>`;
 if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);
}
function offersView(){return `<div class="section-top"><div><h2 class="section-title">Подобрали для вас</h2><div class="section-meta"><i></i>${esc(COMPANY.region)}<span>·</span>На основе закупочных потребностей</div></div><label class="search">${icon('search')}<input type="search" id="offer-search" placeholder="Найти товар" aria-label="Найти товар" value="${esc(query)}"></label></div><div class="toolbar"><div class="chips" role="group" aria-label="Категория товаров">${['Все','Упаковка','Для офиса','Хозтовары','Избранное'].map(c=>`<button class="chip ${category===c?'active':''}" data-action="category" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><select class="sort-select" id="sort" aria-label="Сортировка"><option value="saving" ${sort==='saving'?'selected':''}>Сначала выгодные</option><option value="deadline" ${sort==='deadline'?'selected':''}>Ближайшие сроки</option><option value="ready" ${sort==='ready'?'selected':''}>Группа собрана</option></select></div><div class="offers-grid" id="offers-grid">${offerCards()}</div><div class="aside-banner"><span class="banner-icon">${icon('file')}</span><div><h3>Не нашли нужный товар?</h3><p>Добавьте потребность. Мы сопоставим её с предложениями поставщиков.</p></div><button class="text-button" data-action="new-need">Добавить потребность${icon('arrow','sm')}</button></div>`;}
function filtered(){let items=OFFERS.filter(o=>(category==='Все'||category===o.category||(category==='Избранное'&&state.favorites.includes(o.id)))&&(`${o.name} ${o.spec} ${o.supplier}`).toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));items.sort((a,b)=>sort==='deadline'?a.deadline.localeCompare(b.deadline):sort==='ready'?Number(calculate(b).ready)-Number(calculate(a).ready):calculate(b).savingPercent-calculate(a).savingPercent);return items;}
function offerCards(){const offers=filtered();return offers.length?offers.map((o,i)=>{const c=calculate(o),joined=orderFor(o.id);return `<article class="offer-card" style="animation-delay:${Math.min(i,5)*35}ms"><div class="product-visual" style="--visual:${o.accent}"><span class="product-category">${o.category}</span>${product(o.kind)}<button class="icon-button favorite ${state.favorites.includes(o.id)?'active':''}" data-action="favorite" data-id="${o.id}" aria-label="${state.favorites.includes(o.id)?'Убрать из избранного':'В избранное'}: ${o.name}" aria-pressed="${state.favorites.includes(o.id)}">${icon('heart')}</button></div><div class="offer-body"><button class="offer-title" data-action="offer" data-id="${o.id}">${o.name}</button><div class="offer-spec">${o.spec}</div><div class="offer-supplier">${icon('shield')}${o.supplier}</div><div class="offer-price-line"><strong class="offer-price amount">${money(c.groupTotal)}</strong><span class="old-price amount">${money(c.standaloneTotal)}</span><span class="saving">−${percent(c.savingPercent)}</span></div><div class="offer-price-note">За ${number(o.quantity)} ${o.unit} с доставкой</div><div class="group-progress"><div class="progress-head"><span>${icon('users')}${o.participants+1} компаний с вами</span><span>${Math.round(c.progress)}%</span></div><div class="progress ${c.ready?'ready':''}" role="progressbar" aria-label="Объём группы" aria-valuenow="${Math.round(c.progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${c.progress}%"></i></div></div><div class="offer-bottom"><span>${icon('clock')}Сбор до ${date(o.deadline)}</span><span>${c.ready?'Объём набран':'Идёт сбор группы'}</span></div><button class="offer-button" data-action="offer" data-id="${o.id}">${joined?'Вы участвуете': 'Посмотреть предложение'}${icon(joined?'check':'arrow')}</button></div></article>`;}).join(''):`<div class="empty"><div class="empty-icon">${icon('search')}</div><h3>${category==='Избранное'?'Пока нет избранных предложений':'Подходящих предложений пока нет'}</h3><p>${category==='Избранное'?'Нажмите на сердечко в карточке, чтобы сохранить предложение.':'Попробуйте другую категорию или добавьте свою потребность.'}</p>${button('Показать все предложения','clear-filter','secondary')}</div>`;}
function ordersView(){const orders=state.orders.filter(o=>orderFilter==='all'||(orderFilter==='active'?o.status!=='cancelled':o.status==='cancelled'));return `<div class="section-top"><div><h2 class="section-title">Мои закупки</h2><div class="section-meta">Ваши заявки и согласованные условия</div></div>${button(icon('plus','sm')+'Новая закупка','go-offers','secondary small')}</div><div class="chips mb20">${[['all','Все'],['active','Активные'],['cancelled','Отменённые']].map(([id,label])=>`<button class="chip ${orderFilter===id?'active':''}" data-action="order-filter" data-filter="${id}">${label}</button>`).join('')}</div>${orders.length?orders.map(order=>{const o=offerById(order.offerId);return `<article class="order-card"><div class="order-art" style="--visual:${o.accent}">${product(o.kind)}</div><div class="order-info"><div class="badges-line"><span class="status ${order.status==='cancelled'?'gray':order.status==='ready'?'green':'blue'}">${statusLabel(order)}</span></div><h3>${o.name}</h3><p class="order-meta">${order.number} · ${number(order.quantity)} ${o.unit} · ${o.supplier}</p></div><div class="order-price"><strong class="amount">${money(order.calculation.groupTotal)}</strong><small>${order.status==='cancelled'?'Заявка отменена':'Ожидаемая экономия '+money(order.calculation.saving)}</small></div><div class="order-action">${button('Подробнее','order-detail','secondary',`data-id="${order.id}"`)}</div></article>`;}).join(''):`<div class="empty"><div class="empty-icon">${icon('bag')}</div><h3>${orderFilter==='cancelled'?'Отменённых заявок нет':'Здесь будут ваши закупки'}</h3><p>Выберите подходящее предложение и подтвердите участие. Условия и расчёт сохранятся в этом разделе.</p>${button('Выбрать предложение','go-offers','primary')}</div>`}`;}
function statusLabel(o){return o.status==='cancelled'?'Отменена':o.status==='ready'?'Объём группы набран':'Сбор группы';}
function needsView(){return `<div class="section-top"><div><h2 class="section-title">Потребности бизнеса</h2><div class="section-meta">Товары, которые нужны вашей компании</div></div>${button(icon('plus','sm')+'Добавить','new-need','primary')}</div>${state.needs.length?`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Товар</th><th>Количество</th><th>Нужен до</th><th>Предложение</th><th></th></tr></thead><tbody>${state.needs.map(n=>{const o=matchNeed(n,OFFERS);return `<tr><td><div class="cell-main">${esc(n.name)}</div><div class="cell-sub">${esc(n.spec)}</div></td><td>${number(n.quantity)} ${esc(n.unit)}</td><td>${date(n.deadline)}</td><td>${o?`<button class="text-button" data-action="offer" data-id="${o.id}" data-quantity="${n.quantity}" data-price="${n.price}">Подобрано${icon('arrow','sm')}</button>`:`<span class="status gray">Ищем совпадение</span>`}</td><td><button class="icon-button" data-action="delete-need" data-id="${esc(n.id)}" aria-label="Удалить потребность ${esc(n.name)}">${icon('close','sm')}</button></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">${icon('file')}</div><h3>Добавьте первую потребность</h3><p>Укажите товар и сроки, чтобы найти подходящее предложение.</p>${button('Добавить потребность','new-need','primary')}</div>`}<div class="aside-banner"><span class="banner-icon">${icon('upload')}</span><div><h3>Уже есть список закупок?</h3><p>Загрузите позиции из CSV или JSON. Файлы остаются в вашем браузере.</p></div><button class="text-button" data-action="upload">Загрузить${icon('arrow','sm')}</button></div>`;}
function analyticsView(){const active=activeOrders(),saving=active.reduce((sum,o)=>sum+o.calculation.saving,0);const values=OFFERS.map(o=>calculate(o).saving);const max=Math.max(...values);return `<div class="section-top"><div><h2 class="section-title">Аналитика закупок</h2><div class="section-meta">Экономика текущей подборки</div></div>${button(icon('download','sm')+'Выгрузить расчёт','export','secondary')}</div><div class="analytics-grid"><div class="panel chart-card"><div class="chart-header"><h3>Потенциальная экономия по товарам</h3><span class="muted" style="font-size:10px">С доставкой</span></div><div class="chart-layout"><div class="chart-axis"><span>${number(Math.ceil(max/1000))} тыс. ₽</span><span>0 ₽</span></div><div class="chart-bars">${OFFERS.map((o,i)=>`<div class="chart-column"><div class="chart-bar" style="height:${values[i]/max*150}px"><span class="chart-value">${money(values[i])}</span></div><small>${['Пакеты','Бумага','Перчатки','Этикетки','Кофе','Плёнка'][i]}</small></div>`).join('')}</div></div><p class="analytics-note">Расчёт для объёмов в карточках. Условия и цены демонстрационные. Это возможная экономия после набора группы, а не результат проведённых сделок.</p></div><div class="panel chart-card"><h3>Экономия по категориям</h3>${['Упаковка','Для офиса','Хозтовары'].map((cat,i)=>{const val=OFFERS.filter(o=>o.category===cat).reduce((s,o)=>s+calculate(o).saving,0);return `<div class="category-row"><div><span>${cat}</span><span class="amount">${money(val)}</span></div><div class="progress"><i style="width:${val/totals().saving*100}%;background:${['#0866ff','#7b9fe2','#9cbbe8'][i]}"></i></div></div>`;}).join('')}<div class="callout">${icon('info')}По активным заявкам ожидаемая экономия составляет ${money(saving)}. Фактическую экономию можно оценить после выполнения закупки.</div></div></div><div class="panel table-wrap mt16"><table class="data-table"><thead><tr><th>Товар</th><th>Самостоятельно</th><th>В группе</th><th>Экономия</th></tr></thead><tbody>${OFFERS.map(o=>{const c=calculate(o);return `<tr><td><div class="cell-main">${o.name}</div><div class="cell-sub">${number(o.quantity)} ${o.unit}</div></td><td>${money(c.standaloneTotal)}</td><td>${money(c.groupTotal)}</td><td style="color:var(--green)">${money(c.saving)} <small>(${percent(c.savingPercent)})</small></td></tr>`;}).join('')}</tbody></table></div>`;}
function openDialog(d){lastFocus=document.activeElement;dialog=d;renderOverlay();document.body.style.overflow='hidden';setTimeout(()=>overlay.querySelector('button,input,select')?.focus(),30);}
function closeDialog(){dialog=null;overlay.innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function openOffer(id,qty,baselinePrice){const o=offerById(id);if(!o)return;detailTab='terms';openDialog({type:'offer',id,baselinePrice,quantity:qty||orderFor(id)?.quantity||o.quantity,consent:false});}
function renderOverlay(){if(!dialog)return;const d=dialog;if(d.type==='offer'){renderOfferOverlay();return;}if(d.type==='order'){renderOrderOverlay();return;}
 const templates={help:helpModal,privacy:privacyModal,upload:uploadModal,'new-need':needModal,notifications:notificationsModal,profile:profileModal,company:companyModal,success:successModal,review:reviewModal,bank:bankModal};const fn=templates[d.type];if(fn)overlay.innerHTML=fn();setupUpload();}
function modal(title,body,footer='',cls=''){return `<div class="modal-wrap" data-backdrop="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;}
function renderOfferOverlay(){const d=dialog,o={...offerById(d.id),...(d.baselinePrice?{price:d.baselinePrice}:{})},c=calculate(o,d.quantity),joined=orderFor(o.id);
 overlay.innerHTML=`<div class="overlay" data-backdrop="true"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><div><div class="eyebrow">Совместная закупка</div><h2 id="detail-title">Предложение поставщика</h2></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-product"><div class="drawer-product-art" style="--visual:${o.accent}">${product(o.kind)}</div><div><h2>${o.name}</h2><p>${o.spec}</p><div class="mini-supplier">${icon('shield')}${o.supplier} · Демопредложение</div></div></div><nav class="subtabs" aria-label="Детали предложения">${[['terms','Условия'],['group','Состав группы'],['calculation','Расчёт выгоды']].map(([id,label])=>`<button class="${detailTab===id?'active':''}" data-action="detail-tab" data-tab="${id}">${label}</button>`).join('')}</nav>${detailTab==='terms'?`<p class="detail-description">${o.description}</p><label class="form-label" for="quantity">Ваш объём закупки</label><div class="quantity-line"><div class="quantity-control"><button data-action="quantity-down" aria-label="Уменьшить количество">${icon('minus','sm')}</button><input id="quantity" type="number" min="1" max="1000000" step="${o.step}" value="${d.quantity}" aria-label="Количество товара"><button data-action="quantity-up" aria-label="Увеличить количество">${icon('plus','sm')}</button></div><small>${o.unit}<br>Шаг ${o.step} ${o.unit}</small></div><div id="detail-calculation">${priceSummary(o,c)}</div><div class="group-block" id="detail-group">${groupSummary(o,c)}</div><div class="info-row">${icon('clock')}<div><strong>Сбор заявок до ${date(o.deadline)}</strong>Плановая поставка ${date(o.deliveryDate)}. Срок включён в условия предложения.</div></div><div class="info-row">${icon('file')}<div><strong>Отдельный заказ для вашей компании</strong>Поставщик учитывает общий объём, документы и платёж остаются отдельными.</div></div><div class="info-row">${icon('shield')}<div><strong>Правила закупки</strong>Условия зафиксированы в версии 1. При изменении цены или объёма потребуется повторное подтверждение.</div></div>`:detailTab==='group'?groupDetail(o,c):calculationDetail(o,c)}${joined?`<div class="callout">${icon('check')}Вы уже участвуете в этой закупке. Условия вашей заявки доступны в разделе «Мои закупки».</div>`:`<label class="check-label"><input type="checkbox" id="consent" ${d.consent?'checked':''}>Подтверждаю товар, количество и условия участия. При изменении итоговой стоимости я получу обновлённое предложение.</label>`}</div><footer class="drawer-footer">${button(joined?'Открыть мою заявку':c.beneficial?'Проверить и подтвердить':'Участие невыгодно',joined?'open-existing':'review','primary full',(!joined&&(!d.consent||!c.beneficial)?'disabled':'')+` data-id="${o.id}"`)}<p>Подтверждение создаёт демонстрационную заявку. Деньги не списываются.</p></footer></section></div>`;}
function priceSummary(o,c){return `<div class="price-summary"><div class="summary-row"><span>Товар в общей закупке</span><strong class="amount">${money(c.groupGoods)}</strong></div><div class="summary-row"><span>Доставка для вашей компании</span><strong class="amount">${money(o.groupDelivery)}</strong></div><div class="summary-row total"><span>Итого для вас</span><strong class="amount">${money(c.groupTotal)}</strong></div><div class="summary-row green"><span>Экономия с доставкой</span><strong class="amount">${money(c.saving)} · ${percent(c.savingPercent)}</strong></div></div>`;}
function groupSummary(o,c){return `<div class="group-head"><span>${icon('users')} Объём общей закупки</span><strong>${number(c.totalQuantity)} / ${number(o.threshold)} ${o.unit}</strong></div><div class="progress ${c.ready?'ready':''}"><i style="width:${c.progress}%"></i></div><small>${c.ready?'Необходимый объём набран с учётом вашей заявки.':'До оптового объёма осталось '+number(c.missing)+' '+o.unit+' Условия действуют после набора группы.'}</small>`;}
function groupDetail(o,c){return `<div class="group-block">${groupSummary(o,c)}</div><p class="detail-description">Участники объединяют объём. Контактные и банковские данные других компаний не раскрываются.</p>${Array.from({length:Math.min(o.participants,5)},(_,i)=>`<div class="participant"><span class="participant-avatar">${['А','Б','В','Г','Д'][i]}</span><div class="participant-info">Участник ${i+1}<small>Москва и область · Подтверждено</small></div><span class="participant-qty">${number(Math.floor(o.otherQuantity/o.participants)+(i<o.otherQuantity%o.participants?1:0))} ${o.unit}</span></div>`).join('')}${o.participants>5?`<p class="analytics-note">Ещё ${o.participants-5} участников. Общий подтверждённый объём других компаний: ${number(o.otherQuantity)} ${o.unit}</p>`:''}<div class="participant"><span class="participant-avatar" style="background:#e5f0ff;color:var(--blue)">С</span><div class="participant-info">Ваша компания<small>${esc(COMPANY.name)}</small></div><span class="participant-qty">${number(c.quantity)} ${o.unit}</span></div><div class="callout">${icon('info')}После закрытия сбора поставщик подтверждает готовность исполнить закупку. Изменение значимых условий потребует нового согласия участников.</div>`;}
function calculationDetail(o,c){return `<p class="detail-description">Сравниваем одинаковый товар и одинаковое количество. Обе цены включают НДС по условиям демонстрационного предложения.</p><table class="calculation-table"><thead><tr><th>Стоимость</th><th>Самостоятельно</th><th>В группе</th></tr></thead><tbody><tr><td>Цена за ${o.unit}</td><td>${money(o.price)}</td><td>${money(o.groupPrice)}</td></tr><tr><td>Товар, ${number(c.quantity)} ${o.unit}</td><td>${money(c.standaloneGoods)}</td><td>${money(c.groupGoods)}</td></tr><tr><td>Доставка</td><td>${money(o.delivery)}</td><td>${money(o.groupDelivery)}</td></tr><tr><td>Итого</td><td>${money(c.standaloneTotal)}</td><td>${money(c.groupTotal)}</td></tr></tbody></table><div class="price-summary"><div class="summary-row green"><span>Ваша чистая экономия</span><strong>${money(c.saving)} (${percent(c.savingPercent)})</strong></div></div><div class="callout">${icon('info')}Дополнительной комиссии покупателю в этом сценарии нет. Возможное вознаграждение банку учитывается поставщиком в своём предложении и не прибавляется к итогу скрытым платежом.</div><p class="analytics-note">Расчёт действует при наборе минимального объёма группы. Стоимость хранения, финансирования и ожидания здесь не учитывается: для пилота эти расходы нужно согласовать отдельно.</p>`;}
function reviewModal(){const o={...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})},c=calculate(o,dialog.quantity);return modal('Подтверждение участия',`<p class="modal-desc">Проверьте условия перед созданием заявки. Общий объём не меняет ваш индивидуальный заказ.</p><div class="attachment-row mb20">${icon('box')}<div><p>${o.name}</p><small>${o.spec}</small></div><strong>${number(c.quantity)} ${o.unit}</strong></div>${priceSummary(o,c)}<div class="menu-row"><span>Поставщик</span><strong>${o.supplier}</strong></div><div class="menu-row"><span>Плановая поставка</span><strong>${date(o.deliveryDate)}</strong></div><div class="menu-row"><span>Версия условий</span><strong>1</strong></div>${!c.ready?`<div class="callout warning">${icon('clock')}Группа ещё собирается. Цена действует при достижении ${number(o.threshold)} ${o.unit} до ${date(o.deadline)}.</div>`:''}<div class="callout">${icon('shield')}В деморежиме подтверждение сохраняется в браузере. Банковская подпись и списание не выполняются.</div>`,button('Назад','back-offer','secondary')+button('Подтвердить участие','confirm','primary'));}
function successModal(){const o=offerById(dialog.id),order=state.orders.find(x=>x.id===dialog.orderId);return modal('',`<div class="success-body"><div class="success-art">${icon('check')}</div><div class="success-order">${order.number}</div><h2>Вы в закупке</h2><p>Заявка на ${number(order.quantity)} ${o.unit} добавлена. Условия и расчёт доступны в разделе «Мои закупки».</p><div class="price-summary"><div class="summary-row"><span>Стоимость вашей закупки</span><strong>${money(order.calculation.groupTotal)}</strong></div><div class="summary-row green"><span>Ожидаемая экономия</span><strong>${money(order.calculation.saving)}</strong></div></div></div>`,button('К предложениям','success-offers','secondary')+button('Мои закупки','success-orders','primary'));}
function helpModal(){return modal('Как работает Оптима',`<p class="modal-desc">Условия крупной закупки, даже если вам нужна небольшая партия.</p><div class="help-steps">${[['Укажите, что нужно бизнесу','Добавьте товар вручную или загрузите список закупок. Подбор учитывает характеристики и срок.'],['Выберите общую закупку','Сравните полную стоимость, необходимый объём и предложение поставщика.'],['Подтвердите свой заказ','Вы покупаете только нужное количество. При изменении условий сервис запросит подтверждение заново.'],['Следите за состоянием группы','После набора объёма поставщик подтверждает исполнение. В текущем прототипе показан этап согласования.']].map(([t,b],i)=>`<div class="help-step"><span class="step-number">${i+1}</span><div><h3>${t}</h3><p>${b}</p></div></div>`).join('')}</div>`,button('Понятно','close','primary'));}
function privacyModal(){return modal('Данные и условия',`<p class="modal-desc">«Оптима» является прототипом команды для Академии Финтеха. Это концепция интеграции в ВТБ, а не действующий банковский сервис.</p><div class="help-steps"><div class="info-row">${icon('shield')}<div><strong>Демонстрационные данные</strong>Компания, поставщики, цены и заявки вымышлены. Реальных списаний и юридически значимых подписей нет.</div></div><div class="info-row">${icon('file')}<div><strong>Файлы обрабатываются локально</strong>CSV и JSON читаются в браузере. Не загружайте реальные конфиденциальные документы в демонстрацию.</div></div><div class="info-row">${icon('users')}<div><strong>Банковская интеграция</strong>В будущем подключаются разрешённые данные клиентов с их согласием. Платежи содержат суммы и контрагентов, документы уточняют товары и количество.</div></div><div class="info-row">${icon('settings')}<div><strong>Состояние сохраняется на устройстве</strong>Избранное, потребности и заявки хранятся в localStorage. Их можно сбросить для нового показа.</div></div></div>`,button('Сбросить демоданные','reset-ask','tertiary')+button('Понятно','close','primary'));}
function needModal(){return modal('Новая потребность',`<p class="modal-desc">Укажите товар и необходимый объём. Точное описание поможет найти совместимую закупку.</p><form id="need-form"><div class="field"><label for="need-product">Товар</label><select id="need-product" class="input" name="product"><option value="">Выберите или укажите свой</option>${OFFERS.map(o=>`<option value="${o.id}">${o.name}</option>`).join('')}<option value="custom">Другой товар</option></select></div><div class="field"><label for="need-name">Название товара</label><input class="input" id="need-name" name="name" required placeholder="Например, курьерские пакеты" maxlength="120"></div><div class="field"><label for="need-spec">Характеристики</label><input class="input" id="need-spec" name="spec" required placeholder="Размер, материал, упаковка" maxlength="200"></div><div class="field-grid"><div class="field"><label for="need-quantity">Количество</label><input class="input" id="need-quantity" name="quantity" type="number" min="1" max="1000000" required placeholder="1 000"></div><div class="field"><label for="need-unit">Единица измерения</label><select class="input" id="need-unit" name="unit"><option>шт.</option><option>пач.</option><option>уп.</option><option>рул.</option><option>кг</option></select></div><div class="field"><label for="need-price">Текущая цена за единицу, ₽</label><input class="input" id="need-price" name="price" type="number" min="0.01" step="0.01" required placeholder="3,40"></div><div class="field"><label for="need-deadline">Нужно получить до</label><input class="input" id="need-deadline" name="deadline" type="date" min="2026-10-17" required value="2026-10-29"></div></div><div id="form-error"></div></form>`,button('Отмена','close','secondary')+`<button class="btn primary" type="submit" form="need-form">Добавить потребность</button>`);}
function uploadModal(){if(dialog.rows)return modal('Проверка позиций',`<p class="modal-desc">Распознано позиций: ${dialog.rows.length}. Проверьте товары перед добавлением в потребности.</p><div class="file-preview"><table class="data-table"><thead><tr><th>Товар</th><th>Объём</th><th>Цена</th></tr></thead><tbody>${dialog.rows.map(r=>`<tr><td>${esc(r.name)}<div class="cell-sub">${esc(r.spec)}</div></td><td>${number(r.quantity)} ${esc(r.unit)}</td><td>${money(r.price)}</td></tr>`).join('')}</tbody></table></div><div class="callout">${icon('shield')}Данные файла не отправляются в банк или на сервер.</div>`,button('Другой файл','upload','secondary')+button('Добавить позиции','import-needs','primary'));
 return modal('Загрузка закупочных позиций',`<p class="modal-desc">Загрузите выгрузку из учётной системы в CSV или JSON. PDF и изображения можно будет подключить после интеграции распознавания документов.</p><label class="upload-area" id="dropzone" for="file-input">${icon('upload')}<strong>Перетащите файл или выберите на устройстве</strong><small>CSV или JSON, до 1 МБ</small><input type="file" class="file-input" id="file-input" accept=".csv,.json,text/csv,application/json"></label><div class="upload-choice"><button class="text-button" data-action="sample">${icon('download','sm')}Скачать пример CSV</button><button class="text-button" data-action="new-need">Ввести вручную</button></div><div id="upload-error"></div><div class="callout">${icon('info')}Поля файла: name, spec, quantity, unit, price, deadline. Названия колонок также доступны в примере.</div>`);}
function notificationsModal(){return modal('Уведомления',`<div class="notification-item">${icon('box')}<div><p>Для вашей компании доступны ${OFFERS.length} предложений совместных закупок.</p><small>Демонстрационное уведомление</small></div></div>${state.events.length?state.events.slice(0,8).map(e=>`<div class="notification-item">${icon('check')}<div><p>${esc(e.message)}</p><small>${new Date(e.at).toLocaleString('ru-RU')}</small></div></div>`).join(''):`<div class="notification-item">${icon('shield')}<div><p>Действия по заявкам будут появляться здесь.</p><small>Журнал событий</small></div></div>`}`,button('Понятно','close','primary'));}
function profileModal(){return modal('Профиль',`<div class="row-between mb20"><div class="user-avatar" style="width:48px;height:48px;font-size:16px">АС</div><span class="tour-tag">Демонстрационный профиль</span></div><div class="menu-row"><span>Пользователь</span><strong>${COMPANY.owner}</strong></div><div class="menu-row"><span>Компания</span><strong>${esc(COMPANY.name)}</strong></div><div class="menu-row"><span>Роль</span><strong>Руководитель</strong></div><div class="menu-row"><span>Регион закупок</span><strong>${COMPANY.region}</strong></div>`,button('Закрыть','close','primary'));}
function companyModal(){return modal('Ваша компания',`<div class="attachment-row">${icon('briefcase')}<div><p>${esc(COMPANY.name)}</p><small>${COMPANY.region}</small></div><span class="status blue">Демоданные</span></div><p class="modal-desc mt16">В прототипе используется одна тестовая компания. Рабочие данные и переключение организаций будут доступны после подключения банковского API.</p>`,button('Понятно','close','primary'));}
function bankModal(){return modal(esc(dialog.name),`<div class="bank-placeholder">${icon(dialog.name==='Главная'?'home':'wallet')}<h2>Раздел бизнес-банкинга</h2><p>В этом прототипе доступен сервис «Оптима». Навигация показывает, как совместные закупки могут быть встроены в банковский кабинет.</p></div>`,button('Вернуться в Оптиму','success-offers','primary'));}
function renderOrderOverlay(){const order=state.orders.find(o=>o.id===dialog.id),o=offerById(order.offerId);overlay.innerHTML=`<div class="overlay" data-backdrop="true"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><div><div class="eyebrow">${order.number}</div><h2 id="detail-title">Ваша закупка</h2></div><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-product"><div class="drawer-product-art" style="--visual:${o.accent}">${product(o.kind)}</div><div><h2>${o.name}</h2><p>${number(order.quantity)} ${o.unit} · ${o.supplier}</p><div class="mt16"><span class="status ${order.status==='cancelled'?'gray':order.status==='ready'?'green':'blue'}">${statusLabel(order)}</span></div></div></div>${priceSummary(o,order.calculation)}<div class="detail-label">Согласованные условия</div><div class="menu-row"><span>Плановая поставка</span><strong>${date(o.deliveryDate)}</strong></div><div class="menu-row"><span>Версия условий</span><strong>${order.version}</strong></div><div class="menu-row"><span>Ваши документы и платёж</span><span>Отдельно от других участников</span></div><div class="order-timeline"><div class="timeline-item"><span class="timeline-dot">${icon('check')}</span><div><strong>Заявка создана</strong>${new Date(order.createdAt).toLocaleString('ru-RU')}</div></div><div class="timeline-item"><span class="timeline-dot">${icon('check')}</span><div><strong>Условия версии ${order.version} подтверждены</strong>Сохранены количество, стоимость и согласие участника</div></div><div class="timeline-item"><span class="timeline-dot">${icon(order.status==='cancelled'?'close':'clock')}</span><div><strong>${order.status==='cancelled'?'Участие отменено':order.status==='ready'?'Объём группы набран':'Ожидание набора группы'}</strong>${order.status==='cancelled'?'Деньги не списывались':'Следующий этап: подтверждение поставщика'}</div></div></div><div class="callout">${icon('info')}Документооборот, банковские платежи и отслеживание доставки пока не подключены. Заявка моделирует согласование участия.</div></div><footer class="drawer-footer">${button(icon('download','sm')+'Выгрузить условия','download-order','secondary full',`data-id="${order.id}"`)}${order.status!=='cancelled'?`<button class="text-button" data-action="cancel-ask" data-id="${order.id}" style="width:100%;justify-content:center;margin-top:8px;color:#a08b8b">Отменить участие</button>`:''}</footer></section></div>`;}
function toast(message){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>{const root=$('#toast-root');if(root)root.innerHTML='';},3600);}
function switchView(v){view=v;closeDialog();render();$('.sidebar')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function refreshOffers(){if($('#offers-grid'))$('#offers-grid').innerHTML=offerCards();}
function updateQuantity(q){if(!dialog||dialog.type!=='offer')return;const o={...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})};dialog.quantity=Math.max(1,Math.min(1000000,Math.round(q)||1));const c=calculate(o,dialog.quantity);if($('#quantity'))$('#quantity').value=dialog.quantity;if($('#detail-calculation'))$('#detail-calculation').innerHTML=priceSummary(o,c);if($('#detail-group'))$('#detail-group').innerHTML=groupSummary(o,c);const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=!dialog.consent||!c.beneficial;}
function download(text,name,type='text/plain'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportCsv(){const head='Товар;Количество;Самостоятельно;В группе;Экономия;Экономия, %\n';const rows=OFFERS.map(o=>{const c=calculate(o);return [o.name,o.quantity,c.standaloneTotal,c.groupTotal,c.saving,c.savingPercent.toFixed(2)].join(';');}).join('\n');download('\uFEFF'+head+rows,'optima-calculation.csv','text/csv;charset=utf-8');toast('Расчёт подготовлен к скачиванию');}
function sampleCsv(){download('\uFEFFname;spec;quantity;unit;price;deadline\nКурьерские пакеты;250 × 350 мм, 50 мкм;1000;шт.;3.4;2026-10-26\nБумага для офиса;А4, 80 г/м², 500 листов;10;пач.;440;2026-10-28','optima-needs-example.csv','text/csv;charset=utf-8');}
async function readFile(file){if(!file)return;try{if(file.size>1024*1024)throw new Error('Максимальный размер файла — 1 МБ');if(!/\.(csv|json)$/i.test(file.name))throw new Error('Выберите CSV или JSON');const rows=parseNeeds(await file.text(),file.name);dialog={type:'upload',rows};renderOverlay();}catch(e){$('#upload-error').innerHTML=`<div class="error-message">${esc(e.message)}</div>`;}}
function setupUpload(){const z=$('#dropzone');if(z){z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('dragging');});z.addEventListener('dragleave',()=>z.classList.remove('dragging'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('dragging');readFile(e.dataTransfer.files[0]);});$('#file-input').addEventListener('change',e=>readFile(e.target.files[0]));}}
const actions={
 view:b=>switchView(b.dataset.view),category:b=>{category=b.dataset.category;render();},'clear-filter':()=>{category='Все';query='';render();},'go-offers':()=>switchView('offers'),
 offer:b=>openOffer(b.dataset.id,Number(b.dataset.quantity)||undefined,Number(b.dataset.price)||undefined),favorite:b=>{const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();refreshOffers();},
 close:closeDialog,help:()=>openDialog({type:'help'}),privacy:()=>openDialog({type:'privacy'}),profile:()=>openDialog({type:'profile'}),company:()=>openDialog({type:'company'}),bank:b=>openDialog({type:'bank',name:b.dataset.name}),
 notifications:()=>{state.notificationsRead=true;save();render();openDialog({type:'notifications'});},mobile:()=>$('.sidebar').classList.toggle('open'),'mobile-close':()=>$('.sidebar').classList.remove('open'),
 'global-search':()=>{switchView('offers');$('#offer-search')?.focus();},'new-need':()=>openDialog({type:'new-need'}),upload:()=>openDialog({type:'upload'}),sample:sampleCsv,export:exportCsv,
 'detail-tab':b=>{detailTab=b.dataset.tab;renderOfferOverlay();},'quantity-down':()=>updateQuantity(dialog.quantity-offerById(dialog.id).step),'quantity-up':()=>updateQuantity(dialog.quantity+offerById(dialog.id).step),
 review:()=>{if(!dialog.consent||dialog.quantityValid===false)return;dialog={...dialog,type:'review'};renderOverlay();},'back-offer':()=>{dialog={...dialog,type:'offer'};renderOverlay();},
 confirm:()=>{const d=dialog,o={...offerById(d.id),...(d.baselinePrice?{price:d.baselinePrice}:{})};if(orderFor(o.id)){toast('Вы уже участвуете в закупке');return;}const calculation=calculate(o,d.quantity);if(!calculation.beneficial)return;const order={id:crypto.randomUUID(),number:'ЗК-'+String(1001+state.orders.length),offerId:o.id,quantity:d.quantity,calculation,version:1,status:calculation.ready?'ready':'collecting',createdAt:new Date().toISOString()};state.orders.unshift(order);addEvent(state,`Создана заявка ${order.number}: ${o.name}`);save();render();dialog={type:'success',id:o.id,orderId:order.id};renderOverlay();},
 'open-existing':b=>{const o=orderFor(b.dataset.id);if(o){dialog={type:'order',id:o.id};renderOverlay();}},'order-detail':b=>openDialog({type:'order',id:b.dataset.id}),
 'success-offers':()=>switchView('offers'),'success-orders':()=>switchView('orders'),'order-filter':b=>{orderFilter=b.dataset.filter;render();},
 'delete-need':b=>{const n=state.needs.find(n=>n.id===b.dataset.id);dialog={type:'delete-need',id:n.id};overlay.innerHTML=modal('Удалить потребность?',`<p class="modal-desc">${esc(n.name)} будет удалён из списка. Это не отменяет уже созданную заявку на закупку.</p>`,button('Оставить','close','secondary')+button('Удалить','delete-need-confirm','danger'));document.body.style.overflow='hidden';},
 'delete-need-confirm':()=>{state.needs=state.needs.filter(n=>n.id!==dialog.id);save();closeDialog();render();toast('Потребность удалена');},
 'import-needs':()=>{const rows=dialog.rows;rows.forEach(row=>state.needs.push({...row,id:crypto.randomUUID(),source:'Загружено из файла'}));addEvent(state,`Загружено потребностей: ${rows.length}`);save();switchView('needs');toast(`Добавлено позиций: ${rows.length}`);},
 'download-order':b=>{const order=state.orders.find(o=>o.id===b.dataset.id),o=offerById(order.offerId);download(JSON.stringify({demo:true,company:COMPANY.name,product:o.name,specification:o.spec,supplier:o.supplier,deliveryDate:o.deliveryDate,...order},null,2),`optima-${order.number}.json`,'application/json');toast('Условия заявки подготовлены');},
 'cancel-ask':b=>{dialog={type:'cancel',id:b.dataset.id};overlay.innerHTML=modal('Отменить участие?',`<p class="modal-desc">Ваша заявка перестанет участвовать в сборе группы. При повторном присоединении потребуется заново подтвердить актуальные условия.</p><div class="callout">${icon('info')}В демонстрации деньги не списывались. В реальной системе последствия отказа определяются согласованными условиями.</div>`,button('Сохранить участие','close','secondary')+button('Отменить участие','cancel-confirm','danger'));},
 'cancel-confirm':()=>{const order=state.orders.find(o=>o.id===dialog.id);order.status='cancelled';addEvent(state,`Участие в закупке ${order.number} отменено`);save();switchView('orders');toast('Участие отменено. Деньги не списывались');},
 'reset-ask':()=>{dialog={type:'reset'};overlay.innerHTML=modal('Сбросить демонстрацию?',`<p class="modal-desc">Сохранённые в этом браузере заявки, избранное и загруженные позиции будут удалены. Начальные примеры появятся заново.</p>`,button('Отмена','close','secondary')+button('Сбросить','reset-confirm','danger'));},
 'reset-confirm':()=>{localStorage.removeItem('optima-vtb-state-v1');state=loadState();category='Все';query='';switchView('offers');toast('Демонстрация сброшена');}
};
document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]')){closeDialog();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const f=actions[b.dataset.action];if(f)f(b);});
document.addEventListener('input',e=>{if(e.target.id==='offer-search'){query=e.target.value;refreshOffers();}if(e.target.id==='quantity'){dialog.quantityValid=e.target.value!==''&&Number.isInteger(Number(e.target.value))&&Number(e.target.value)>0;if(dialog.quantityValid)updateQuantity(Number(e.target.value));else{const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=true;}}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;refreshOffers();}if(e.target.id==='consent'&&dialog?.type==='offer'){dialog.consent=e.target.checked;const b=overlay.querySelector('[data-action="review"]');if(b)b.disabled=!dialog.consent||dialog.quantityValid===false||!calculate({...offerById(dialog.id),...(dialog.baselinePrice?{price:dialog.baselinePrice}:{})},dialog.quantity).beneficial;}
 if(e.target.id==='need-product'){const o=offerById(e.target.value);if(o){$('#need-name').value=o.name;$('#need-spec').value=o.spec;$('#need-quantity').value=o.quantity;$('#need-unit').value=o.unit;$('#need-price').value=o.price;$('#need-deadline').value=o.deliveryDate;}}
});
document.addEventListener('submit',e=>{if(e.target.id!=='need-form')return;e.preventDefault();const row=Object.fromEntries(new FormData(e.target));row.quantity=Number(row.quantity);row.price=Number(row.price);const errors=validateNeed(row);if(errors.length){$('#form-error').innerHTML=`<div class="error-message">${errors.map(esc).join('<br>')}</div>`;return;}state.needs.push({...row,id:crypto.randomUUID(),source:'Добавлено вручную'});addEvent(state,`Добавлена потребность: ${row.name}`);save();switchView('needs');toast(matchNeed(row,OFFERS)?'Потребность добавлена. Подобрано предложение':'Потребность добавлена. Ищем совместимое предложение');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){closeDialog();return;}if(e.key==='Tab'&&dialog){const f=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),select,a[href],textarea')].filter(x=>x.offsetParent!==null);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['offers','orders','needs','analytics'].includes(v)&&v!==view)switchView(v);});
const initialView=location.hash.slice(1);if(['offers','orders','needs','analytics'].includes(initialView))view=initialView;
render();
